import net.minecraft.util.Mth;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.StructureBlockEntity;

public class LocationTask extends AbstractBooleanTask {
	private ResourceKey<Level> dimension;
	private boolean ignoreDimension;
	private int x, y, z;
	private int w, h, d;

	public LocationTask(long id, Quest quest) {
		super(id, quest);

		dimension = Level.OVERWORLD;
		ignoreDimension = false;
		x = y = z = 0;
		w = h = d =  1;
	}

	public void initFromStructure(StructureBlockEntity structure) {
		var pos = structure.getStructurePos();
		var size = structure.getStructureSize();
		dimension = structure.getLevel().dimension();
		x = pos.getX() + structure.getBlockPos().getX();
		y = pos.getY() + structure.getBlockPos().getY();
		z = pos.getZ() + structure.getBlockPos().getZ();
		w = Math.max(1, size.getX());
		h = Math.max(1, size.getY());
		d = Math.max(1, size.getZ());
	}

	@Override
	public TaskType getType() {
		return TaskTypes.LOCATION;
	}

	@Override
	public void writeData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.writeData(nbt, provider);
		nbt.putString("dimension", dimension.location().toString());
		nbt.putBoolean("ignore_dimension", ignoreDimension);
		nbt.putIntArray("position", new int[]{x, y, z});
		nbt.putIntArray("size", new int[]{w, h, d});
	}

	@Override
	public void readData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.readData(nbt, provider);
		dimension = ResourceKey.create(Registries.DIMENSION, ResourceLocation.tryParse(nbt.getString("dimension")));
		ignoreDimension = nbt.getBoolean("ignore_dimension");

		int[] pos = nbt.getIntArray("position");

		if (pos.length == 3) {
			x = pos[0];
			y = pos[1];
			z = pos[2];
		}

		int[] size = nbt.getIntArray("size");

		if (pos.length == 3) {
			w = size[0];
			h = size[1];
			d = size[2];
		}
	}

	@Override
	public void writeNetData(RegistryFriendlyByteBuf buffer) {
		super.writeNetData(buffer);
		buffer.writeResourceLocation(dimension.location());
		buffer.writeBoolean(ignoreDimension);
		buffer.writeVarInt(x);
		buffer.writeVarInt(y);
		buffer.writeVarInt(z);
		buffer.writeVarInt(w);
		buffer.writeVarInt(h);
		buffer.writeVarInt(d);
	}

	@Override
	public void readNetData(RegistryFriendlyByteBuf buffer) {
		super.readNetData(buffer);
		dimension = ResourceKey.create(Registries.DIMENSION, buffer.readResourceLocation());
		ignoreDimension = buffer.readBoolean();
		x = buffer.readVarInt();
		y = buffer.readVarInt();
		z = buffer.readVarInt();
		w = buffer.readVarInt();
		h = buffer.readVarInt();
		d = buffer.readVarInt();
	}

	@Override
	@Environment(EnvType.CLIENT)
	public void fillConfigGroup(ConfigGroup config) {
		super.fillConfigGroup(config);
		config.addString("dim", dimension.location().toString(), v -> dimension = ResourceKey.create(Registries.DIMENSION, ResourceLocation.tryParse(v)), "minecraft:overworld");
		config.addBool("ignore_dim", ignoreDimension, v -> ignoreDimension = v, false);
		config.addInt("x", x, v -> x = v, 0, Integer.MIN_VALUE, Integer.MAX_VALUE);
		config.addInt("y", y, v -> y = v, 0, Integer.MIN_VALUE, Integer.MAX_VALUE);
		config.addInt("z", z, v -> z = v, 0, Integer.MIN_VALUE, Integer.MAX_VALUE);
		config.addInt("w", w, v -> w = v, 1, 1, Integer.MAX_VALUE);
		config.addInt("h", h, v -> h = v, 1, 1, Integer.MAX_VALUE);
		config.addInt("d", d, v -> d = v, 1, 1, Integer.MAX_VALUE);
	}

	@Override
	public int autoSubmitOnPlayerTick() {
		return 3;
	}

	@Override
	public boolean canSubmit(TeamData teamData, ServerPlayer player) {
		if (ignoreDimension || dimension == player.level().dimension()) {
			int py = Mth.floor(player.getY());

			if (py >= y && py < y + h) {
				int px = Mth.floor(player.getX());

				if (px >= x && px < x + w) {
					int pz = Mth.floor(player.getZ());
					return pz >= z && pz < z + d;
				}
			}
		}

		return false;
	}
}

package dev.ftb.mods.ftbquests.quest.task;

import dev.architectury.hooks.level.entity.PlayerHooks;
import dev.ftb.mods.ftblibrary.config.ConfigGroup;
import dev.ftb.mods.ftblibrary.integration.stages.StageHelper;
import dev.ftb.mods.ftbquests.quest.Quest;
import dev.ftb.mods.ftbquests.quest.ServerQuestFile;
import dev.ftb.mods.ftbquests.quest.TeamData;
import dev.ftb.mods.ftbteams.api.FTBTeamsAPI;
import dev.ftb.mods.ftbteams.api.TeamStagesHelper;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.ChatFormatting;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.server.level.ServerPlayer;

public class StageTask extends AbstractBooleanTask {
	private String stage = "";
	private boolean teamStage = false;

	public StageTask(long id, Quest quest) {
		super(id, quest);
	}

	@Override
	public TaskType getType() {
		return TaskTypes.STAGE;
	}

	@Override
	public void writeData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.writeData(nbt, provider);
		nbt.putString("stage", stage);
		if (teamStage) {
			nbt.putBoolean("team_stage", true);
		}
	}

	@Override
	public void readData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.readData(nbt, provider);
		stage = nbt.getString("stage");
		teamStage = nbt.getBoolean("team_stage");
	}

	@Override
	public void writeNetData(RegistryFriendlyByteBuf buffer) {
		super.writeNetData(buffer);
		buffer.writeUtf(stage, Short.MAX_VALUE);
		buffer.writeBoolean(teamStage);
	}

	@Override
	public void readNetData(RegistryFriendlyByteBuf buffer) {
		super.readNetData(buffer);
		stage = buffer.readUtf(Short.MAX_VALUE);
		teamStage = buffer.readBoolean();
	}

	@Override
	@Environment(EnvType.CLIENT)
	public void fillConfigGroup(ConfigGroup config) {
		super.fillConfigGroup(config);
		config.addString("stage", stage, v -> stage = v, "").setNameKey("ftbquests.task.ftbquests.gamestage");
		config.addBool("team_stage", teamStage, v -> teamStage = v, false);
	}

	@Override
	public MutableComponent getAltTitle() {
		return Component.translatable("ftbquests.task.ftbquests.gamestage").append(": ").append(Component.literal(stage).withStyle(ChatFormatting.YELLOW));
	}

	@Override
	public int autoSubmitOnPlayerTick() {
		return 20;
	}

	@Override
	public boolean canSubmit(TeamData teamData, ServerPlayer player) {
        if (teamStage) {
			return FTBTeamsAPI.api().getManager().getTeamByID(teamData.getTeamId())
					.map(team -> TeamStagesHelper.hasTeamStage(team, stage))
					.orElse(false);
		} else {
			return StageHelper.INSTANCE.getProvider().has(player, stage);
		}
    }

	@SuppressWarnings("unused")
	public static void checkStages(ServerPlayer player) {
		// hook for FTB XMod Compat to call into
		if (ServerQuestFile.INSTANCE == null || PlayerHooks.isFake(player)) {
			return;
		}

		ServerQuestFile.INSTANCE.getTeamData(player).ifPresent(data -> {
			if (!data.isLocked()) {
				ServerQuestFile.INSTANCE.withPlayerContext(player, () -> {
					for (Task task : ServerQuestFile.INSTANCE.getAllTasks()) {
						if (task instanceof StageTask && data.canStartTasks(task.getQuest())) {
							task.submitTask(data, player);
						}
					}
				});
			}
		});
	}
}
